import {tenantProject} from '../../public/lib/tenant.js';
export function featureProject(){const p=tenantProject();p.name='Example Ministry';p.domain='https://example.org';p.pages=p.pages.filter(x=>x.id!=='about');Object.assign(p.pages[0].blocks[0],{title:'Welcome',text:'Example mission text',button:'Our programs',href:'/programs/',secondaryButton:'Donate',secondaryHref:'/donate/'});const programs=p.pages.find(x=>x.id==='programs');programs.blocks[1]={id:'food',anchor:'food-pantry',type:'hero',title:'Example service',text:'Service details',button:'Contact',href:'/contact/'};p.donation.url='https://www.paypal.com/donate/?hosted_button_id=EXAMPLE';p.socials=[{label:'Community',url:'https://example.org/news'},{label:'Photos',url:'https://example.org/photos'}];p.pages.find(x=>x.id==='contact').blocks.push({type:'social',title:'Social media'});p.pages.find(x=>x.id==='team').blocks[1].items=[{title:'Example Person',text:'Director'}];return p;}
